FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL; (* Sensor de paso de pieza *)
    sensorAltura    : BOOL; (* Sensor de altura: TRUE = pieza alta *)
END_VAR
VAR_OUTPUT
    banda   : BOOL; (* Banda transportadora activa *)
    piston  : BOOL; (* Pistón desviador *)
    nAltas  : INT;  (* Contador de piezas altas *)
    nBajas  : INT;  (* Contador de piezas bajas *)
END_VAR
VAR
    tRetardo : TON; (* Retardo de 2 s hasta llegar al desviador *)
    tPulso   : TP;  (* Pulso de 1 s para activar el pistón *)
    rPresencia : R_TRIG; (* Flanco ascendente del sensor de presencia *)
    bPiezaAlta : BOOL;   (* Indica que la pieza detectada es alta *)
END_VAR

(* La banda funciona siempre *)
banda := TRUE;

(* Detectar flanco ascendente del sensor de presencia *)
rPresencia(CLK := sensorPresencia);

IF rPresencia.Q THEN
    IF sensorAltura THEN
        (* Pieza alta: registrar y armar retardo *)
        nAltas     := nAltas + 1;
        bPiezaAlta := TRUE;
    ELSE
        (* Pieza baja: solo contar *)
        nBajas := nBajas + 1;
    END_IF;
END_IF;

(* Retardo de 2 s: la pieza tarda ese tiempo en llegar al desviador *)
tRetardo(IN := bPiezaAlta, PT := T#2S);

(* Al cumplirse el retardo, lanzar pulso de 1 s en el pistón *)
tPulso(IN := tRetardo.Q, PT := T#1S);

(* Cuando el pulso termina, limpiar la bandera de pieza alta *)
IF NOT tPulso.Q AND NOT tRetardo.Q AND bPiezaAlta THEN
    (* El temporizador de retardo aún no ha arrancado o ya terminó el pulso *)
    (* Limpiar solo cuando el ciclo completo haya concluido *)
    IF tRetardo.ET = T#0S AND NOT tRetardo.IN THEN
        bPiezaAlta := FALSE;
    END_IF;
END_IF;

(* Limpiar bandera al finalizar el pulso del pistón *)
IF tPulso.Q = FALSE AND tRetardo.Q = FALSE AND tRetardo.ET >= T#2S THEN
    bPiezaAlta := FALSE;
END_IF;

(* Activar pistón durante el pulso de 1 s *)
piston := tPulso.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL; // Sensor que detecta el paso de una pieza
    sensorAltura : BOOL;    // Sensor que detecta si la pieza es alta
END_VAR

VAR_OUTPUT
    banda : BOOL;           // Salida para activar la banda transportadora
    piston : BOOL;          // Salida para activar el pistón desviador
    nAltas : INT := 0;      // Contador de piezas altas
    nBajas : INT := 0;      // Contador de piezas bajas
END_VAR

VAR
    trigPresencia : R_TRIG; // Detector de flanco de subida para el sensor de presencia
    esperaPiston : BOOL;    // Marca de memoria para iniciar el retardo del pistón
    tonRetardo : TON;       // Temporizador de retardo (llegada al desviador)
    tpPiston : TP;          // Temporizador de pulso (duración de activación del pistón)
END_VAR

// 1. La banda funciona continuamente
banda := TRUE;

// 2. Detección del paso de una pieza (flanco de subida)
trigPresencia(CLK := sensorPresencia);

IF trigPresencia.Q THEN
    IF sensorAltura THEN
        // Es una pieza alta
        nAltas := nAltas + 1;
        esperaPiston := TRUE; // Se activa la bandera para iniciar el retardo
    ELSE
        // Es una pieza baja
        nBajas := nBajas + 1;
    END_IF;
END_IF;

// 3. Temporizador de retardo: espera 2 segundos a que la pieza llegue al pistón
tonRetardo(IN := esperaPiston, PT := T#2S);

// Al cumplirse los 2 segundos, se apaga la marca de espera
IF tonRetardo.Q THEN
    esperaPiston := FALSE; 
END_IF;

// 4. Temporizador de pulso: activa el pistón durante 1 segundo
// Se dispara con el flanco de subida de tonRetardo.Q
tpPiston(IN := tonRetardo.Q, PT := T#1S);

// 5. Asignación de la salida física del pistón
piston := tpPiston.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL; // Sensor que detecta la presencia de una pieza
    sensorAltura : BOOL;    // Sensor que detecta si la pieza es alta
END_VAR

VAR_OUTPUT
    banda : BOOL := TRUE;   // Salida que activa la banda transportadora
    piston : BOOL := FALSE; // Salida que activa el pistón desviador
    nAltas : INT := 0;      // Contador de piezas altas
    nBajas : INT := 0;      // Contador de piezas bajas
END_VAR

VAR
    estadoAnteriorPresencia : BOOL := FALSE; // Estado anterior del sensor de presencia
    temporizadorRetraso : TON;              // Temporizador para el retraso de 2 segundos
    temporizadorPiston : TON;               // Temporizador para la duración de 1 segundo del pistón
    activarPiston : BOOL := FALSE;          // Bandera para activar el pistón
END_VAR

// Inicialización de los temporizadores
temporizadorRetraso(IN := FALSE, PT := T#2S);
temporizadorPiston(IN := FALSE, PT := T#1S);

// Detectar flanco de subida del sensor de presencia
IF (sensorPresencia AND NOT estadoAnteriorPresencia) THEN
    IF sensorAltura THEN
        // Iniciar temporizador de retraso para piezas altas
        temporizadorRetraso(IN := TRUE);
        activarPiston := TRUE;
    ELSE
        // Incrementar contador de piezas bajas
        nBajas := nBajas + 1;
    END_IF;
END_IF;

// Actualizar estado anterior del sensor de presencia
estadoAnteriorPresencia := sensorPresencia;

// Control del pistón
IF activarPiston THEN
    // Si el temporizador de retraso ha terminado, iniciar temporizador del pistón
    IF temporizadorRetraso.Q THEN
        temporizadorPiston(IN := TRUE);
        temporizadorRetraso(IN := FALSE);
    END_IF;

    // Activar el pistón durante 1 segundo
    IF temporizadorPiston.Q THEN
        piston := FALSE;
        temporizadorPiston(IN := FALSE);
        activarPiston := FALSE;
        nAltas := nAltas + 1; // Incrementar contador de piezas altas
    ELSE
        piston := TRUE;
    END_IF;
ELSE
    piston := FALSE;
END_IF;

banda := TRUE; // La banda siempre está activa
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL; // Sensor de presencia de pieza
    sensorAltura : BOOL;    // Sensor de altura de pieza
END_VAR

VAR_OUTPUT
    banda : BOOL;          // Salida para activar la banda
    piston : BOOL;         // Salida para activar el pistón
    nAltas : INT;          // Contador de piezas altas
    nBajas : INT;          // Contador de piezas bajas
END_VAR

VAR
    timer1 : TON;           // Timer para esperar 2 segundos
    timer2 : TON;           // Timer para activar el pistón durante 1 segundo
    piezaDetectada : BOOL;  // Bandera para detectar pieza
END_VAR

// Inicialización de variables
IF NOT piezaDetectada THEN
    timer1(IN := FALSE);
    timer2(IN := FALSE);
    piston := FALSE;
END_IF

// Detectar pieza
IF sensorPresencia AND NOT piezaDetectada THEN
    piezaDetectada := TRUE;
    timer1(IN := TRUE);
    timer1(PTR := T#2S);
END_IF

// Esperar 2 segundos antes de evaluar la altura
IF timer1.Q THEN
    timer1(IN := FALSE);
    IF sensorAltura THEN
        nAltas := nAltas + 1;
        timer2(IN := TRUE);
        timer2(PTR := T#1S);
        piston := TRUE;
    ELSE
        nBajas := nBajas + 1;
    END_IF
END_IF

// Activar el pistón durante 1 segundo
IF timer2.Q THEN
    timer2(IN := FALSE);
    piston := FALSE;
END_IF

// Mantener la banda activa
banda := TRUE;

// Reiniciar la bandera de detección de pieza
IF sensorPresencia = FALSE THEN
    piezaDetectada := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL;  // Sensor que detecta la presencia de una pieza
    sensorAltura : BOOL;     // Sensor que detecta si la pieza es alta
END_VAR

VAR_OUTPUT
    banda : BOOL;            // Salida para activar la banda transportadora
    piston : BOOL;           // Salida para activar el pistón desviador
    nAltas : INT;            // Contador de piezas altas
    nBajas : INT;            // Contador de piezas bajas
END_VAR

VAR
    timerRetraso : TON;      // Temporizador para retrasar la activación del pistón
    timerDuracion : TON;     // Temporizador para la duración del pistón activado
    presenciaDetectada : BOOL; // Indica si se ha detectado una pieza
    piezaAlta : BOOL;        // Indica si la pieza detectada es alta
END_VAR

// Inicialización de la banda transportadora
banda := TRUE;

// Detección de una pieza
IF sensorPresencia AND NOT presenciaDetectada THEN
    presenciaDetectada := TRUE;
    piezaAlta := sensorAltura;

    // Iniciar temporizador de retraso si la pieza es alta
    IF piezaAlta THEN
        timerRetraso(IN := TRUE, PT := T#2S);
    ELSE
        nBajas := nBajas + 1; // Incrementar contador de piezas bajas
    END_IF
END_IF

// Manejo del temporizador de retraso
IF timerRetraso.Q THEN
    timerRetraso(IN := FALSE);
    timerDuracion(IN := TRUE, PT := T#1S);
    piston := TRUE;
END_IF

// Manejo del temporizador de duración del pistón
IF timerDuracion.Q THEN
    timerDuracion(IN := FALSE);
    piston := FALSE;
    nAltas := nAltas + 1; // Incrementar contador de piezas altas
END_IF

// Reiniciar detección de presencia
IF NOT sensorPresencia THEN
    presenciaDetectada := FALSE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Clasificadora
VAR_INPUT
    sensorPresencia : BOOL; (* Sensor de presencia de pieza *)
    sensorAltura : BOOL; (* Sensor de altura de pieza *)
END_VAR
VAR_OUTPUT
    banda : BOOL; (* Salida de la banda transportadora *)
    piston : BOOL; (* Salida del pistón para desviar piezas altas *)
    nAltas : INT; (* Contador de piezas altas *)
    nBajas : INT; (* Contador de piezas bajas *)
END_VAR
VAR
    tEspera : TP; (* Temporizador para esperar 2 segundos *)
    tPiston : TP; (* Temporizador para activar el pistón durante 1 segundo *)
    piezaDetectada : BOOL; (* Bandera para indicar que una pieza ha sido detectada *)
END_VAR

(* La banda funciona continuamente *)
banda := TRUE;

(* Contador de piezas altas y bajas *)
IF sensorPresencia AND NOT piezaDetectada THEN
    piezaDetectada := TRUE;
    IF sensorAltura THEN
        nAltas := nAltas + 1;
    ELSE
        nBajas := nBajas + 1;
    END_IF;
END_IF;

(* Temporizador para esperar 2 segundos después de detectar una pieza *)
tEspera(IN := piezaDetectada, PT := T#2S);

(* Temporizador para activar el pistón durante 1 segundo *)
IF tEspera.Q THEN
    piston := TRUE;
    tPiston(IN := TRUE, PT := T#1S);
ELSE
    piston := FALSE;
END_IF;

(* Reiniciar la bandera de pieza detectada cuando el temporizador del pistón termina *)
IF tPiston.Q THEN
    piezaDetectada := FALSE;
END_IF;

END_FUNCTION_BLOCK
